// --- GLOBALS ---

def genus_species = 'Listeria monocytogenes'

def schema = 'l_mono_chewie_1748_220623'

// --- INLINE PROCESSES ---

// --- SUB WORKFLOWS ---

workflow wf_listeria_typing {

    take:

        trimmed


    main:
        trimmed.multiMap {
            trimmed: it
            genus_species: genus_species
            schema: schema
        }.set { prep }

        assembly = step_2AS_denovo__spades(prep.trimmed)
        step_4TY_cgMLST__chewbbaca(assembly.assembled, prep.genus_species, prep.schema)
        step_4TY_MLST__mlst(assembly.assembled)

}

// --- ENTRYPOINT ---
workflow {
    wf_listeria_typing(step_1PP_trimming__fastp(getSingleInput()).trimmed)
}

