workflow wf_species_confirmation {

    take:

        assembled


    main:
        kmerfinder(assembled)
        assigned_species = kmerfinder.out.check.map { [ it[0], getCalculatedSpecies(it[1]), getBacterialReferencePath(it[1]) ] }

    emit:

        assigned_species


}

workflow wf_resistance_gene_detection {

    take:

        assembled


    main:
        abricate(assembled)

}

// --- ENTRYPOINT ---
