include { getInput; hasEnoughFastqData; hasFastqData } from '../functions/parameters.nf'

include { step_1PP_trimming__fastp } from '../steps/step_1PP_trimming__fastp'

// --- GLOBALS ---

// --- INLINE PROCESSES ---

// --- SUB WORKFLOWS ---

workflow module_reads_processing {

    take:

        rawReads


    main:
        rawReads.branch {
            with_data: hasFastqData(it[1])
            no_reads: true
        }.set { ch_raw }

        proc_fastp = step_1PP_trimming__fastp(ch_raw.with_data)

        proc_fastp.trimmed.branch {
            with_data: hasEnoughFastqData(it[1])
            insufficient: true
        }.set { ch_final }

        assembly_result = assembly(ch_final.with_data)

        qc_result = qc_quast(assembly_result)

    emit:

